package lol.pyr.znpcsplus.fabric.npc;
import lol.pyr.znpcsplus.fabric.hologram.Hologram;import lol.pyr.znpcsplus.fabric.interaction.NpcAction;import lol.pyr.znpcsplus.fabric.skin.SkinDescriptor;import lol.pyr.znpcsplus.fabric.util.NpcLocation;import java.util.*;import java.util.concurrent.*;
public final class Npc{public String id;public UUID uuid=UUID.randomUUID();public String world;public String type="player";public NpcLocation location;public boolean enabled=true;public boolean processed=true;public boolean allowCommands=true;public boolean save=true;public final Map<String,String> properties=new LinkedHashMap<>();public final List<NpcAction> actions=new ArrayList<>();public final Hologram hologram=new Hologram();public transient SkinDescriptor skin;public transient int entityId;public transient final Set<UUID> viewers=ConcurrentHashMap.newKeySet();public transient final Map<UUID,float[]> perPlayerLook=new ConcurrentHashMap<>();public transient final Map<UUID,Long> interactionDebounce=new ConcurrentHashMap<>();public transient final List<Integer> hologramEntityIds=new ArrayList<>();
 public Npc(){} public Npc(String id,String world,String type,NpcLocation loc){this.id=id;this.world=world;this.type=type;location=loc;}
 public String prop(String n,String d){String v=properties.get(n.toLowerCase(Locale.ROOT));return v==null?d:v;}public boolean bool(String n,boolean d){return Boolean.parseBoolean(prop(n,Boolean.toString(d)));}public int integer(String n,int d){try{return Integer.parseInt(prop(n,Integer.toString(d)));}catch(Exception e){return d;}}public long longValue(String n,long d){try{return Long.parseLong(prop(n,Long.toString(d)));}catch(Exception e){return d;}}public double number(String n,double d){try{return Double.parseDouble(prop(n,Double.toString(d)));}catch(Exception e){return d;}}public float decimal(String n,float d){try{return Float.parseFloat(prop(n,Float.toString(d)));}catch(Exception e){return d;}}
}